-- Fictional tokens remain in this rolled-back test transaction only.
RESET ROLE;
INSERT INTO firstten_policy_test.ids(label,id) VALUES('invite_project','f9500000-0000-4000-8000-000000000001'),('invite_other','f9500000-0000-4000-8000-000000000002');
INSERT INTO public.projects(id,user_id,name) VALUES(firstten_policy_test.id('invite_project'),firstten_policy_test.id('owner_a'),'Invitation fixture'),(firstten_policy_test.id('invite_other'),firstten_policy_test.id('owner_b'),'Foreign invitation fixture');
INSERT INTO public.contacts(id,user_id,project_id,first_name) VALUES('f9500000-0000-4000-8000-000000000003',firstten_policy_test.id('owner_a'),firstten_policy_test.id('invite_project'),'Private participant');
INSERT INTO public.interviews(id,user_id,project_id,answers) VALUES('f9500000-0000-4000-8000-000000000004',firstten_policy_test.id('owner_a'),firstten_policy_test.id('invite_project'),'[{"note":"Private original evidence"}]');
CREATE TABLE firstten_policy_test.invite_results(label text PRIMARY KEY,result jsonb);
GRANT SELECT,INSERT ON firstten_policy_test.invite_results TO authenticated;
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='firstten_private.project_invitations'::regclass),'invitation table RLS enabled');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.project_invitations','SELECT,INSERT,UPDATE,DELETE'),'authenticated users cannot read token table directly');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.project_invitations','SELECT,INSERT,UPDATE,DELETE'),'service role has no token-table shortcut');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.invitation_operations','SELECT,INSERT,UPDATE,DELETE'),'operation journal inaccessible');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.invitation_audit','SELECT,INSERT,UPDATE,DELETE'),'audit inaccessible');
SELECT ok(NOT has_function_privilege('anon','public.accept_project_invitation(text,text)','EXECUTE'),'anonymous acceptance denied by ACL');
SELECT ok(NOT has_function_privilege('service_role','public.create_project_invitation(text,uuid,uuid,text,integer,uuid)','EXECUTE'),'service role cannot issue owner invitations');
SELECT ok((SELECT bool_and(prosecdef AND proconfig=ARRAY['search_path=pg_catalog']) FROM pg_proc WHERE oid IN ('public.create_project_invitation(text,uuid,uuid,text,integer,uuid)'::regprocedure,'public.list_project_invitations(uuid,uuid)'::regprocedure,'public.revoke_project_invitation(uuid,uuid,uuid)'::regprocedure,'public.accept_project_invitation(text,text)'::regprocedure)),'all public invitation RPCs use fixed search paths');
UPDATE firstten_private.project_collaboration_capability SET enabled=false;
SELECT firstten_policy_test.set_actor('owner_a'); SET LOCAL ROLE authenticated;
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'viewer',7,gen_random_uuid())->>'code','FEATURE_DISABLED','issue remains gated with collaboration disabled');
SELECT is(public.accept_project_invitation('project',repeat('a',64))->>'code','FEATURE_DISABLED','acceptance remains gated');
SELECT is(jsonb_array_length(public.list_project_invitations(firstten_policy_test.id('invite_project'))#>'{data,items}'),0,'owner can inspect invitations while disabled');
SELECT is(public.create_project_invitation('class',gen_random_uuid(),firstten_policy_test.id('student'),'student',7,gen_random_uuid())->>'code','FEATURE_DISABLED','future student-only class target disabled');
SELECT is(public.create_project_invitation('class',gen_random_uuid(),firstten_policy_test.id('student'),'teacher',7,gen_random_uuid())->>'code','INVALID_INPUT','class target cannot request teacher');
SELECT is(public.create_project_invitation('class',gen_random_uuid(),firstten_policy_test.id('student'),'admin',7,gen_random_uuid())->>'code','INVALID_INPUT','class target cannot request administrator');
SELECT is(public.accept_project_invitation('class',repeat('a',64))->>'code','FEATURE_DISABLED','unsupported class token cannot be consumed');
RESET ROLE; UPDATE firstten_private.project_collaboration_capability SET enabled=true;
SELECT firstten_policy_test.set_actor('owner_a'); SET LOCAL ROLE authenticated;
INSERT INTO firstten_policy_test.invite_results SELECT 'viewer',public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'viewer',7,'f9500000-0000-4000-8000-000000000011');
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.invite_results WHERE label='viewer'),'true','owner creates explicit recipient viewer invitation');
SELECT ok((SELECT result->>'token' ~ '^[0-9a-f]{64}$' FROM firstten_policy_test.invite_results WHERE label='viewer'),'database returns random 256-bit token');
SELECT is((SELECT result->>'replayed' FROM firstten_policy_test.invite_results WHERE label='viewer'),'false','first response carries one-time secret');
SELECT is((SELECT count(*) FROM jsonb_object_keys((SELECT result->'data' FROM firstten_policy_test.invite_results WHERE label='viewer'))),8::bigint,'owner metadata contains exactly eight approved fields');
INSERT INTO firstten_policy_test.invite_results SELECT 'replay',public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'viewer',7,'f9500000-0000-4000-8000-000000000011');
SELECT is((SELECT result->'data' FROM firstten_policy_test.invite_results WHERE label='replay'),(SELECT result->'data' FROM firstten_policy_test.invite_results WHERE label='viewer'),'create retry returns same invitation metadata');
SELECT ok((SELECT result->>'token' IS NULL AND result->>'replayed'='true' FROM firstten_policy_test.invite_results WHERE label='replay'),'hash-only replay never regenerates or recovers secret');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'editor',7,'f9500000-0000-4000-8000-000000000011')->>'code','IDEMPOTENCY_CONFLICT','changed role cannot reuse create request');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_other'),firstten_policy_test.id('viewer'),'viewer',7,gen_random_uuid())->>'code','NOT_FOUND','owner cannot invite to foreign project');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('owner_a'),'viewer',7,gen_random_uuid())->>'code','INVALID_INPUT','owner cannot demote self by invitation');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'owner',7,gen_random_uuid())->>'code','INVALID_INPUT','owner role never invitable');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'admin',7,gen_random_uuid())->>'code','INVALID_INPUT','admin role never invitable');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'viewer',31,gen_random_uuid())->>'code','INVALID_INPUT','maximum expiry is thirty days');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'viewer',0,gen_random_uuid())->>'code','INVALID_INPUT','nonpositive expiry rejected');
INSERT INTO firstten_policy_test.invite_results SELECT 'thirty',public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('student'),'viewer',30,gen_random_uuid());
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.invite_results WHERE label='thirty'),'true','exact thirty-day maximum works in long-running transaction');
INSERT INTO firstten_policy_test.invite_results SELECT 'competing',public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'editor',7,gen_random_uuid());
INSERT INTO firstten_policy_test.invite_results SELECT 'expired',public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('editor'),'editor',7,gen_random_uuid());
INSERT INTO firstten_policy_test.invite_results SELECT 'revoked',public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('editor'),'viewer',7,gen_random_uuid());
RESET ROLE;
SELECT ok((SELECT i.token_hash=encode(sha256(convert_to(r.result->>'token','UTF8')),'hex') AND i.token_hash<>r.result->>'token' FROM firstten_private.project_invitations i JOIN firstten_policy_test.invite_results r ON i.id=(r.result#>>'{data,id}')::uuid WHERE r.label='viewer'),'only token hash is durable');
SELECT ok(NOT EXISTS(SELECT 1 FROM firstten_private.invitation_operations j JOIN firstten_policy_test.invite_results r ON j.result->>'id'=r.result#>>'{data,id}' WHERE r.label='viewer' AND j.result::text LIKE '%'||(r.result->>'token')||'%'),'idempotency journal contains no plaintext token');
UPDATE firstten_private.project_invitations SET created_at=statement_timestamp()-interval '2 days',expires_at=statement_timestamp()-interval '1 day' WHERE id=(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.invite_results WHERE label='expired');
SELECT firstten_policy_test.set_actor('owner_a'); SET LOCAL ROLE authenticated;
INSERT INTO firstten_policy_test.invite_results SELECT 'revoke-ack',public.revoke_project_invitation(firstten_policy_test.id('invite_project'),(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.invite_results WHERE label='revoked'),'f9500000-0000-4000-8000-000000000012');
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.invite_results WHERE label='revoke-ack'),'true','owner revokes link');
SELECT is(public.revoke_project_invitation(firstten_policy_test.id('invite_project'),(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.invite_results WHERE label='revoked'),'f9500000-0000-4000-8000-000000000012'),(SELECT result FROM firstten_policy_test.invite_results WHERE label='revoke-ack'),'revoke retry is idempotent');
SELECT is(public.set_owned_project_archived(firstten_policy_test.id('invite_project'),true,0,gen_random_uuid())->>'ok','true','archive fixture before new issue/acceptance');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),'viewer',7,gen_random_uuid())->>'code','NOT_FOUND','archived project cannot issue invites');
RESET ROLE; SELECT firstten_policy_test.set_actor('viewer'); SET LOCAL ROLE authenticated;
SELECT is(public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='viewer'))->>'code','NOT_FOUND','archived project rejects previously issued invitation');
RESET ROLE; SELECT firstten_policy_test.set_actor('owner_a'); SET LOCAL ROLE authenticated;
SELECT is(public.set_owned_project_archived(firstten_policy_test.id('invite_project'),false,1,gen_random_uuid())->>'ok','true','restore invitation fixture');
RESET ROLE; SELECT firstten_policy_test.set_actor('owner_b'); SET LOCAL ROLE authenticated;
SELECT is(public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='viewer'))->>'code','NOT_FOUND','wrong recipient cannot accept known token');
SELECT is(public.list_project_invitations(firstten_policy_test.id('invite_project'))->>'code','NOT_FOUND','foreign owner cannot enumerate invitations');
SELECT is(public.revoke_project_invitation(firstten_policy_test.id('invite_project'),(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.invite_results WHERE label='viewer'),gen_random_uuid())->>'code','NOT_FOUND','foreign owner cannot revoke invitations');
RESET ROLE; SELECT firstten_policy_test.set_actor('editor'); SET LOCAL ROLE authenticated;
SELECT is(public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='expired'))->>'code','NOT_FOUND','expired token rejected');
SELECT is(public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='revoked'))->>'code','NOT_FOUND','revoked token rejected');
RESET ROLE; SELECT firstten_policy_test.set_actor('viewer'); SET LOCAL ROLE authenticated;
INSERT INTO firstten_policy_test.invite_results SELECT 'accepted',public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='viewer'));
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.invite_results WHERE label='accepted'),'true','named recipient accepts invitation');
SELECT is((SELECT result#>>'{data,role}' FROM firstten_policy_test.invite_results WHERE label='accepted'),'viewer','acceptance uses only stored role');
SELECT is(public.current_project_role(firstten_policy_test.id('invite_project')),'viewer','fixed viewer membership materialized');
SELECT is(public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='viewer')),(SELECT result FROM firstten_policy_test.invite_results WHERE label='accepted'),'same recipient retry returns same receipt without another mutation');
SELECT is(public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='competing'))->>'code','REVISION_CONFLICT','competing stale editor invitation cannot escalate current viewer');
SELECT is(public.current_project_role(firstten_policy_test.id('invite_project')),'viewer','stale invitation leaves viewer role intact');
SELECT is(firstten_policy_test.visible_count('projects',firstten_policy_test.id('invite_project')),0::bigint,'invitation never grants private project row');
SELECT is(firstten_policy_test.visible_count('contacts','f9500000-0000-4000-8000-000000000003'),0::bigint,'invitation never grants private contacts');
SELECT is(firstten_policy_test.visible_count('interviews','f9500000-0000-4000-8000-000000000004'),0::bigint,'invitation never grants private interview notes');
SELECT is(public.list_project_invitations(firstten_policy_test.id('invite_project'))->>'code','NOT_FOUND','invited viewer cannot enumerate token metadata');
SELECT is(public.create_project_invitation('project',firstten_policy_test.id('invite_project'),firstten_policy_test.id('editor'),'editor',7,gen_random_uuid())->>'code','NOT_FOUND','invited viewer cannot issue new invitations');
RESET ROLE; SELECT firstten_policy_test.set_actor('owner_a'); SET LOCAL ROLE authenticated;
SELECT is(public.revoke_project_member(firstten_policy_test.id('invite_project'),firstten_policy_test.id('viewer'),1,gen_random_uuid())->>'ok','true','owner revokes accepted membership');
RESET ROLE; SELECT firstten_policy_test.set_actor('viewer'); SET LOCAL ROLE authenticated;
SELECT is(public.accept_project_invitation('project',(SELECT result->>'token' FROM firstten_policy_test.invite_results WHERE label='viewer'))->>'code','NOT_FOUND','accepted token cannot restore revoked membership');
SELECT is(public.current_project_role(firstten_policy_test.id('invite_project')),NULL,'revoked viewer remains revoked');
RESET ROLE;
SELECT is((SELECT count(*) FROM firstten_private.invitation_audit WHERE project_id=firstten_policy_test.id('invite_project') AND operation='accept'),1::bigint,'acceptance retries and denials produce only one acceptance audit');
SELECT ok((SELECT created_by=firstten_policy_test.id('owner_a') AND user_id=firstten_policy_test.id('viewer') FROM public.project_members WHERE project_id=firstten_policy_test.id('invite_project')),'invitation preserves owner grantor and recipient identity');
UPDATE firstten_private.project_collaboration_capability SET enabled=false;
SELECT firstten_policy_test.set_actor('owner_a'); SET LOCAL ROLE authenticated;
SELECT is(public.revoke_project_invitation(firstten_policy_test.id('invite_project'),(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.invite_results WHERE label='viewer'),gen_random_uuid())->>'ok','true','owner can revoke link while collaboration disabled');
SELECT ok(jsonb_array_length(public.list_project_invitations(firstten_policy_test.id('invite_project'))#>'{data,items}')>0,'owner can inspect known invitations while disabled');
RESET ROLE; SELECT set_config('request.jwt.claim.sub','',true),set_config('request.jwt.claims','{}',true); SET LOCAL ROLE authenticated;
SELECT is(public.accept_project_invitation('project',repeat('a',64))->>'code','AUTH_REQUIRED','subjectless authenticated role cannot consume');
RESET ROLE; SET LOCAL ROLE anon;
SELECT is(firstten_policy_test.attempt($case$SELECT public.accept_project_invitation('project',repeat('a',64))$case$),'error:42501','actual anonymous role cannot call invitation RPC');
RESET ROLE;
